source("smoke_firm_dir/code/fxns/1_paths.R")
library(data.table)
root <- file.path(OUT_DIR,"dynamic_entry_exit")
files <- c(file.path(root,"constant_marginal_costs_2026-11-03/entrant_calibration_observations.csv"),file.path(root,"independent_transitions_2026-11-03/assigned_observations.csv"),file.path(root,"independent_transitions_2026-11-03/joint_state_grid.csv"))
hashes <- tools::md5sum(files)
cost <- fread(files[1]);states <- fread(files[2]);grid <- fread(files[3])
stopifnot(!anyDuplicated(cost[,.(brand,month)]),!anyDuplicated(states[,.(brand,month)]))
d <- merge(cost,states[,.(brand,month,quality,xi,quality_state,xi_state)],by=c("brand","month"),all.x=TRUE)
stopifnot(nrow(d)==60L,uniqueN(d$brand)==5L,!anyNA(d),all(d$q>0))
weights <- d[,.(volume_mL=sum(q),observations=.N),by=.(quality_state,xi_state)]
g <- merge(grid,weights,by=c("quality_state","xi_state"),all.x=TRUE)
g[is.na(volume_mL),`:=`(volume_mL=0,observations=0L)]
g[,probability:=volume_mL/sum(d$q)];setorder(g,state)
stopifnot(abs(sum(g$probability)-1)<1e-12,sum(g$observations)==60L,sum(g$volume_mL)==sum(d$q))
out <- file.path(root,"entrant_quality_2026-11-04");dir.create(out,recursive=TRUE,showWarnings=FALSE)
fwrite(g,file.path(out,"entrant_initial_state_distribution.csv"))
fwrite(d,file.path(out,"calibration_observations.csv"))
m <- rbindlist(list(g[,.(probability=sum(probability)),by=.(bin=quality_state)][,variable:="nicotine"],g[,.(probability=sum(probability)),by=.(bin=xi_state)][,variable:="xi"]))
fwrite(m,file.path(out,"marginal_probabilities.csv"))
saveRDS(list(G_e=g,method="Joint empirical distribution weighted by mL over same 60 initial-year observations as entrant MC",revelation_timing="Initial nicotine and xi revealed after sunk-cost commitment; use drawn initial state directly at next-month activation"),file.path(out,"entrant_quality_inputs.rds"))
stopifnot(identical(unname(hashes),unname(tools::md5sum(files))))
fwrite(data.table(path=files,md5=unname(hashes)),file.path(out,"input_hashes.csv"))
writeLines(c("Same five firms, first twelve calendar incumbent months and pooled mL weights as entrant MC calibration.","Map observations to existing three pooled bins for each variable; retain existing within-bin median representatives.","G_e is a joint initial-state distribution, not a transition matrix. Independence of continuing nicotine/xi transitions does not require independent initial draws.","Zero cells are empirical calibration zeros; no smoothing imposed. Entry-state realization revealed after commitment, before next-month pricing; no extra transition before activation.","Initial-year roster states are a successful-expansion benchmark, not verified startup quality. Historical composition and JUUL volume concentration apply.","Five firms and 60 observations reconciled; source hashes unchanged. Dynamic model remains unsolved."),file.path(out,"README.txt"))
print(g[,.(state,quality_state,xi_state,quality,xi,observations,probability)])
